        getSubjectBySlug: subjectBySlug,
        getWorksheets: filterWorksheets,
        getWorksheetById: worksheetById,
        getProducts: function () { return PRODUCTS.slice(); },
        getArticles: function () { return ARTICLES.slice(); },
        searchWorksheets: function (query, filters) {
            return filterWorksheets(Object.assign({}, filters, { query: query }));
        }
